1	//! Tree-sitter query-based pattern matching registry.
2	//!
3	//! Replaces manual recursive AST traversal (`collect_*` methods) with compiled
4	//! tree-sitter queries. Queries are compiled once per (Language, QueryKind) pair
5	//! and cached for reuse.
6	
7	use crate::languages::Language;
8	use std::collections::HashMap;
9	use std::sync::OnceLock;
10	use tree_sitter::Query;
11	
12	/// Categories of structural patterns that can be matched by tree-sitter queries.
13	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
14	pub enum QueryKind {
15	    /// Function/method definitions. Replaces `collect_functions`.
16	    Functions,
17	    /// Function/method call expressions. Replaces `collect_calls`, `collect_all_callees`.
18	    Calls,
19	    /// Assignment expressions and declarations with initializers.
20	    /// Replaces `collect_assignments`, `collect_assignment_paths`.
21	    /// Also used (same query, different extraction) for R-values.
22	    Assignments,
23	    /// Identifier nodes. Replaces `collect_all_identifiers`, `collect_identifiers_at_row`.
24	    /// Also used for `collect_variable_refs` with text post-filter.
25	    Identifiers,
26	    /// Return statements/expressions. Replaces `collect_returns`.
27	    Returns,
28	}
29	
30	/// Global query cache. Compiled once, reused across all ParsedFile instances.
31	static QUERY_CACHE: OnceLock<HashMap<(Language, QueryKind), Query>> = OnceLock::new();
32	
33	/// Get (or initialize) the global query cache.
34	pub fn query_cache() -> &'static HashMap<(Language, QueryKind), Query> {
35	    QUERY_CACHE.get_or_init(|| {
36	        let mut cache = HashMap::new();
37	        for lang in Language::all() {
38	            for kind in [
39	                QueryKind::Functions,
40	                QueryKind::Calls,
41	                QueryKind::Assignments,
42	                QueryKind::Identifiers,
43	                QueryKind::Returns,
44	            ] {
45	                if let Some(pattern) = query_pattern(lang, kind) {
46	                    let ts_lang = lang.tree_sitter_language();
47	                    match Query::new(&ts_lang, pattern) {
48	                        Ok(query) => {
49	                            cache.insert((lang, kind), query);
50	                        }
51	                        Err(e) => {
52	                            // Log but don't panic — fallback to manual traversal.
53	                            eprintln!(
54	                                "Warning: failed to compile {:?} query for {:?}: {}",
55	                                kind, lang, e
56	                            );
57	                        }
58	                    }
59	                }
60	            }
61	        }
62	        cache
63	    })
64	}
65	
66	/// Get a compiled query for a (Language, QueryKind) pair, if available.
67	pub fn get_query(lang: Language, kind: QueryKind) -> Option<&'static Query> {
68	    query_cache().get(&(lang, kind))
69	}
70	
71	/// Return the tree-sitter query pattern string for a given (Language, QueryKind).
72	///
73	/// Each pattern uses named captures (`@name`) that the caller extracts after
74	/// running the query. Returns `None` if the language doesn't support this query.
75	fn query_pattern(lang: Language, kind: QueryKind) -> Option<&'static str> {
76	    match kind {
77	        QueryKind::Functions => function_query(lang),
78	        QueryKind::Calls => call_query(lang),
79	        QueryKind::Assignments => assignment_query(lang),
80	        QueryKind::Identifiers => identifier_query(lang),
81	        QueryKind::Returns => return_query(lang),
82	    }
83	}
84	
85	// ---------------------------------------------------------------------------
86	// Functions query — matches function/method definitions
87	// ---------------------------------------------------------------------------
88	// Capture: @func — the function definition node
89	
90	fn function_query(lang: Language) -> Option<&'static str> {
91	    Some(match lang {
92	        Language::Python => {
93	            r#"[
94	                (function_definition) @func
95	                (decorated_definition) @func
96	            ]"#
97	        }
98	        Language::JavaScript => {
99	            r#"[
100	                (function_declaration) @func
101	                (method_definition) @func
102	                (arrow_function) @func
103	                (function_expression) @func
104	                (generator_function_declaration) @func
105	            ]"#
106	        }
107	        Language::TypeScript | Language::Tsx => {
108	            r#"[
109	                (function_declaration) @func
110	                (method_definition) @func
111	                (arrow_function) @func
112	                (function_expression) @func
113	                (generator_function_declaration) @func
114	            ]"#
115	        }
116	        Language::Go => {
117	            r#"[
118	                (function_declaration) @func
119	                (method_declaration) @func
120	            ]"#
121	        }
122	        Language::Java => {
123	            r#"[
124	                (method_declaration) @func
125	                (constructor_declaration) @func
126	            ]"#
127	        }
128	        Language::C => "(function_definition) @func",
129	        Language::Cpp => {
130	            r#"[
131	                (function_definition) @func
132	                (template_declaration) @func
133	            ]"#
134	        }
135	        Language::Rust => "(function_item) @func",
136	        Language::Lua => "(function_declaration) @func",
137	        Language::Terraform => "(block) @func",
138	        Language::Bash => "(function_definition) @func",
139	    })
140	}
141	
142	// ---------------------------------------------------------------------------
143	// Calls query — matches function/method call expressions
144	// ---------------------------------------------------------------------------
145	// Capture: @call — the call expression node
146	
147	fn call_query(lang: Language) -> Option<&'static str> {
148	    Some(match lang {
149	        Language::Python => "(call) @call",
150	        Language::JavaScript => {
151	            r#"[
152	                (call_expression) @call
153	                (jsx_self_closing_element) @call
154	                (jsx_opening_element) @call
155	            ]"#
156	        }
157	        Language::TypeScript => "(call_expression) @call",
158	        Language::Tsx => {
159	            r#"[
160	                (call_expression) @call
161	                (jsx_self_closing_element) @call
162	                (jsx_opening_element) @call
163	            ]"#
164	        }
165	        Language::Go => "(call_expression) @call",
166	        Language::Java => {
167	            r#"[
168	                (method_invocation) @call
169	                (object_creation_expression) @call
170	            ]"#
171	        }
172	        Language::C | Language::Cpp => "(call_expression) @call",
173	        Language::Rust => {
174	            r#"[
175	                (call_expression) @call
176	                (macro_invocation) @call
177	            ]"#
178	        }
179	        Language::Lua => "(function_call) @call",
180	        Language::Terraform => "(function_call) @call",
181	        Language::Bash => "(command) @call",
182	    })
183	}
184	
185	// ---------------------------------------------------------------------------
186	// Assignments query — matches assignment expressions and declarations
187	// ---------------------------------------------------------------------------
188	// Capture: @assign — the assignment or declaration node
189	
190	fn assignment_query(lang: Language) -> Option<&'static str> {
191	    Some(match lang {
192	        Language::Python => {
193	            r#"[
194	                (assignment) @assign
195	                (augmented_assignment) @assign
196	                (named_expression) @assign
197	            ]"#
198	        }
199	        Language::JavaScript | Language::TypeScript | Language::Tsx => {
200	            r#"[
201	                (assignment_expression) @assign
202	                (augmented_assignment_expression) @assign
203	                (variable_declarator) @assign
204	            ]"#
205	        }
206	        Language::Go => {
207	            r#"[
208	                (assignment_statement) @assign
209	                (short_var_declaration) @assign
210	                (var_declaration) @assign
211	                (const_declaration) @assign
212	            ]"#
213	        }
214	        Language::Java => {
215	            r#"[
216	                (assignment_expression) @assign
217	                (local_variable_declaration) @assign
218	                (field_declaration) @assign
219	            ]"#
220	        }
221	        Language::C | Language::Cpp => {
222	            r#"[
223	                (assignment_expression) @assign
224	                (update_expression) @assign
225	                (declaration) @assign
226	                (init_declarator) @assign
227	            ]"#
228	        }
229	        Language::Rust => {
230	            r#"[
231	                (assignment_expression) @assign
232	                (compound_assignment_expr) @assign
233	                (let_declaration) @assign
234	            ]"#
235	        }
236	        Language::Lua => {
237	            // tree-sitter-lua uses `variable_declaration` for `local x = 1`
238	            r#"[
239	                (assignment_statement) @assign
240	                (variable_declaration) @assign
241	            ]"#
242	        }
243	        Language::Terraform => "(attribute) @assign",
244	        Language::Bash => "(variable_assignment) @assign",
245	    })
246	}
247	
248	// ---------------------------------------------------------------------------
249	// Identifiers query — matches identifier nodes
250	// ---------------------------------------------------------------------------
251	// Capture: @ident — the identifier node
252	
253	fn identifier_query(lang: Language) -> Option<&'static str> {
254	    // Matches core identifier nodes. Used primarily for find_variable_references
255	    // and find_variable_references_scoped, where we filter by text content anyway.
256	    //
257	    // NOTE: This intentionally does NOT cover all types matched by
258	    // Language::is_identifier_node() (e.g., property_identifier, field_identifier).
259	    // Methods needing broader matching (identifiers_on_line) use the manual path.
260	    Some(match lang {
261	        Language::Python | Language::Go | Language::Java | Language::Lua => "(identifier) @ident",
262	        Language::JavaScript | Language::TypeScript | Language::Tsx => {
263	            r#"[
264	                (identifier) @ident
265	                (shorthand_property_identifier) @ident
266	            ]"#
267	        }
268	        Language::C | Language::Cpp => "(identifier) @ident",
269	        Language::Rust => "(identifier) @ident",
270	        Language::Terraform => {
271	            r#"[
272	                (identifier) @ident
273	                (variable_expr) @ident
274	            ]"#
275	        }
276	        Language::Bash => {
277	            r#"[
278	                (variable_name) @ident
279	                (word) @ident
280	            ]"#
281	        }
282	    })
283	}
284	
285	// ---------------------------------------------------------------------------
286	// Returns query — matches return statements/expressions
287	// ---------------------------------------------------------------------------
288	// Capture: @ret — the return node
289	
290	fn return_query(lang: Language) -> Option<&'static str> {
291	    match lang {
292	        Language::Python
293	        | Language::JavaScript
294	        | Language::TypeScript
295	        | Language::Tsx
296	        | Language::Go
297	        | Language::Java
298	        | Language::C
299	        | Language::Cpp
300	        | Language::Lua => Some("(return_statement) @ret"),
301	        Language::Rust => Some("(return_expression) @ret"),
302	        // Terraform and Bash don't have structural return statements
303	        Language::Terraform | Language::Bash => None,
304	    }
305	}
