312	    /// Count matches for a query against a source string.
313	    fn count_matches(lang: Language, kind: QueryKind, source: &str) -> usize {
314	        let query = get_query(lang, kind).expect("query should exist");
315	        let mut parser = tree_sitter::Parser::new();
316	        parser
317	            .set_language(&lang.tree_sitter_language())
318	            .expect("failed to set language");
319	        let tree = parser.parse(source, None).expect("failed to parse");
320	        let mut cursor = tree_sitter::QueryCursor::new();
321	        let mut matches = cursor.matches(query, tree.root_node(), source.as_bytes());
322	        let mut count = 0;
323	        while let Some(_m) = matches.next() {
324	            count += 1;
325	        }
326	        count
327	    }
