329	    #[test]
330	    fn test_all_queries_compile() {
331	        let cache = query_cache();
332	        // 12 languages × 5 query kinds = 60, minus 2 (Returns is None for Terraform, Bash)
333	        let expected_count = Language::all().len() * 5 - 2;
334	        assert_eq!(
335	            cache.len(),
336	            expected_count,
337	            "all {} queries should compile, but only {} did",
338	            expected_count,
339	            cache.len()
340	        );
341	    }
