485	    /// Verify query-based and manual traversal produce identical results.
486	    ///
487	    /// Runs both code paths on multi-language fixtures and compares the set of
488	    /// matched node line ranges. This catches drift if queries are refined but
489	    /// the manual fallback isn't updated (or vice versa).
490	    #[test]
491	    fn test_query_vs_manual_consistency() {
492	        use crate::ast::ParsedFile;
493	
494	        let fixtures: Vec<(&str, Language, &str)> = vec![
495	            (
496	                "test.py",
497	                Language::Python,
498	                "def foo():\n    bar()\n\ndef baz(x):\n    return x\n",
499	            ),
500	            (
501	                "test.js",
502	                Language::JavaScript,
503	                "function foo() { bar(); }\nconst baz = (x) => x;\n",
504	            ),
505	            (
506	                "test.go",
507	                Language::Go,
508	                "package main\nfunc foo() { bar() }\nfunc baz(x int) int { return x }\n",
509	            ),
510	            (
511	                "test.c",
512	                Language::C,
513	                "void foo() { bar(); }\nint baz(int x) { return x; }\n",
514	            ),
515	            (
516	                "test.rs",
517	                Language::Rust,
518	                "fn foo() { bar(); }\nfn baz(x: i32) -> i32 { x }\n",
519	            ),
520	            (
521	                "test.lua",
522	                Language::Lua,
523	                "local function foo() bar() end\nfunction baz(x) return x end\n",
524	            ),
525	        ];
526	
527	        for (path, lang, source) in &fixtures {
528	            let parsed = ParsedFile::parse(path, source, *lang).unwrap();
529	
530	            // --- Functions: query path vs manual path ---
531	            let query_funcs: Vec<(usize, usize)> = parsed
532	                .all_functions()
533	                .iter()
534	                .map(|n| (n.start_position().row, n.end_position().row))
535	                .collect();
536	
537	            let mut manual_funcs_nodes = Vec::new();
538	            parsed.collect_functions_manual(parsed.tree.root_node(), &mut manual_funcs_nodes);
539	            let manual_funcs: Vec<(usize, usize)> = manual_funcs_nodes
540	                .iter()
541	                .map(|n| (n.start_position().row, n.end_position().row))
542	                .collect();
543	
544	            assert_eq!(
545	                query_funcs, manual_funcs,
546	                "Functions mismatch for {:?} ({}): query={:?} manual={:?}",
547	                lang, path, query_funcs, manual_funcs
548	            );
549	
550	            // --- Calls: query path vs manual path ---
551	            // Run callees_in_function on each detected function, comparing both paths.
552	            for func_node in parsed.all_functions() {
553	                let all_lines: std::collections::BTreeSet<usize> = {
554	                    let (start, end) = parsed.node_line_range(&func_node);
555	                    (start..=end).collect()
556	                };
557	
558	                // Query-based path (used by function_calls_on_lines)
559	                let query_calls = parsed.function_calls_on_lines(&func_node, &all_lines);
560	
561	                // Manual fallback path
562	                let mut manual_calls = Vec::new();
563	                parsed.collect_calls_manual(func_node, &all_lines, &mut manual_calls);
564	
565	                // Compare sorted (name, line) pairs
566	                let mut q: Vec<_> = query_calls.iter().map(|(n, l)| (n.as_str(), *l)).collect();
567	                let mut m: Vec<_> = manual_calls.iter().map(|(n, l)| (n.as_str(), *l)).collect();
568	                q.sort();
569	                m.sort();
570	
571	                assert_eq!(
572	                    q,
573	                    m,
574	                    "Calls mismatch for {:?} ({}) in function at row {}: query={:?} manual={:?}",
575	                    lang,
576	                    path,
577	                    func_node.start_position().row,
578	                    q,
579	                    m
580	                );
581	            }
582	        }
583	    }
