585	    /// Verify Assignments query captures a superset of variable names found by manual walk.
586	    ///
587	    /// The query path may produce slightly different match counts than manual traversal
588	    /// (e.g., query matches `variable_declarator` directly while manual also matches its
589	    /// parent `lexical_declaration`), but the *set of variables and lines* must match.
590	    #[test]
591	    fn test_assignment_query_vs_manual_consistency() {
592	        use crate::ast::ParsedFile;
593	        use std::collections::BTreeSet;
594	
595	        let fixtures: Vec<(&str, Language, &str)> = vec![
596	            (
597	                "test.py",
598	                Language::Python,
599	                "def foo():\n    x = 1\n    y += x\n    z = bar()\n",
600	            ),
601	            (
602	                "test.js",
603	                Language::JavaScript,
604	                "function foo() { let x = 1; x += 2; }\n",
605	            ),
606	            (
607	                "test.go",
608	                Language::Go,
609	                "package main\nfunc foo() { x := 1; x = 2 }\n",
610	            ),
611	            ("test.c", Language::C, "void foo() { int x = 1; x = 2; }\n"),
612	            ("test.rs", Language::Rust, "fn foo() { let x = 1; }\n"),
613	        ];
614	
615	        for (path, lang, source) in &fixtures {
616	            let parsed = ParsedFile::parse(path, source, *lang).unwrap();
617	
618	            for func_node in parsed.all_functions() {
619	                let all_lines: std::collections::BTreeSet<usize> = {
620	                    let (start, end) = parsed.node_line_range(&func_node);
621	                    (start..=end).collect()
622	                };
623	
624	                let query_result = parsed.assignment_lvalues_on_lines(&func_node, &all_lines);
625	
626	                let mut manual_result = Vec::new();
627	                parsed.collect_assignments_manual(func_node, &all_lines, &mut manual_result);
628	
629	                // Compare as sets of (name, line) — query and manual should surface
630	                // the same variable names on the same lines, even if counts differ.
631	                let q: BTreeSet<_> = query_result.iter().map(|(n, l)| (n.as_str(), *l)).collect();
632	                let m: BTreeSet<_> = manual_result
633	                    .iter()
634	                    .map(|(n, l)| (n.as_str(), *l))
635	                    .collect();
636	
637	                assert_eq!(
