pub fn method_owner<'a>(&self, func_node: &Node<'a>) -> Option<Node<'a>> {
    match self {
        Language::Rust => {
            let mut anc = func_node.parent();
            while let Some(n) = anc {
                match n.kind() {
                    "impl_item" => return n.child_by_field_name("type"),
                    "trait_item" => return n.child_by_field_name("name"),
                    "function_item" | "closure_expression" => return None,
                    _ => {}
                }
                anc = n.parent();
            }
            None
        }
        Language::Go => {
            if func_node.kind() != "method_declaration" {
                return None;
            }
            let recv = func_node.child_by_field_name("receiver")?;
            let mut c = recv.walk();
            for ch in recv.children(&mut c) {
                if ch.kind() == "parameter_declaration" {
                    return ch.child_by_field_name("type");
                }
            }
            None
        }
        Language::Python => {
            let mut n = *func_node;
            if let Some(p) = n.parent() {
                if p.kind() == "decorated_definition" {
                    n = p;
                }
            }
            let block = n.parent()?;
            if block.kind() != "block" {
                return None;
            }
            let cls = block.parent()?;
            if cls.kind() == "class_definition" {
                return cls.child_by_field_name("name");
            }
            None
        }
        Language::JavaScript | Language::TypeScript | Language::Tsx => {
            let mut body = func_node.parent()?;
            if matches!(body.kind(), "field_definition" | "public_field_definition") {
                body = body.parent()?;
            }
            if body.kind() != "class_body" {
                return None;
            }
            let cls = body.parent()?;
            if matches!(cls.kind(), "class_declaration" | "class") {
                return cls.child_by_field_name("name");
            }
            None
        }
        Language::Java => {
            let body = func_node.parent()?;
            if body.kind() != "class_body" {
                return None;
            }
            let cls = body.parent()?;
            if matches!(cls.kind(), "class_declaration" | "enum_declaration") {
                return cls.child_by_field_name("name");
            }
            None
        }
        Language::Cpp => {
            let func = if func_node.kind() == "template_declaration" {
                let mut cursor = func_node.walk();
                let inner = func_node
                    .children(&mut cursor)
                    .find(|child| child.kind() == "function_definition")?;
                inner
            } else {
                *func_node
            };

            // In-class definition: ancestor field_declaration_list -> class_specifier.
            let mut anc = func.parent();
            while let Some(n) = anc {
                match n.kind() {
                    "field_declaration_list" => {
                        let cls = n.parent()?;
                        if matches!(cls.kind(), "class_specifier" | "struct_specifier") {
                            return cls.child_by_field_name("name");
                        }
                        return None;
                    }
                    "function_definition" => break,
                    _ => {}
                }
                anc = n.parent();
            }

            // Out-of-line definition: declarator chain contains Foo::bar.
            let mut d = func.child_by_field_name("declarator")?;
            loop {
                if d.kind() == "qualified_identifier" {
                    return d.child_by_field_name("scope");
                }
                d = d.child_by_field_name("declarator")?;
            }
        }
        Language::Lua => {
            let name = func_node.child_by_field_name("name")?;
            if matches!(
                name.kind(),
                "dot_index_expression" | "method_index_expression"
            ) {
                return name
                    .child_by_field_name("table")
                    .or_else(|| name.child_by_field_name("object"));
            }
            None
        }
        _ => None,
    }
}

/// Like `method_owner` but returns the enclosing CLASS DEFINITION node (not its name),
/// for single-file-class languages only. The self-receiver class identity. None for
/// Rust/Go/etc. (methods span files there).
pub fn method_owner_class_node<'a>(&self, func_node: &Node<'a>) -> Option<Node<'a>> {
    match self {
        Language::Python => {
            let mut n = *func_node;
            if let Some(p) = n.parent() {
                if p.kind() == "decorated_definition" {
                    n = p;
                }
            }
            let block = n.parent()?;
            if block.kind() != "block" {
                return None;
            }
            let cls = block.parent()?;
            (cls.kind() == "class_definition").then_some(cls)
        }
        Language::JavaScript | Language::TypeScript | Language::Tsx => {
            let mut body = func_node.parent()?;
            if matches!(body.kind(), "field_definition" | "public_field_definition") {
                body = body.parent()?;
            }
            if body.kind() != "class_body" {
                return None;
            }
            let cls = body.parent()?;
            matches!(cls.kind(), "class_declaration" | "class").then_some(cls)
        }
        _ => None,
    }
